            # Check file exists and is readable
            if not os.path.exists(file_path):
                return False, "File does not exist", 0

            if not os.access(file_path, os.R_OK):
                return False, "File is not readable", 0

            with open(file_path, 'rb') as file:
                # Check file size
                file.seek(0, 2)  # Seek to end
                file_size = file.tell()
                file.seek(0)  # Reset to beginning

                if file_size == 0:
                    return False, "Empty PDF file", 0

                if file_size > 500 * 1024 * 1024:  # 500MB limit
                    return False, f"PDF too large ({file_size/1024/1024:.1f} MB)", 0

                # Try to read PDF
                try:
                    pdf_reader = PyPDF2.PdfReader(file)
                except PyPDF2.errors.PdfReadError as e:
                    return False, f"Invalid PDF format: {e}", 0

                # Check if PDF is encrypted
                if pdf_reader.is_encrypted:
                    try:
                        # Try to decrypt with empty password
                        pdf_reader.decrypt('')
                    except:
                        return False, "PDF is encrypted and cannot be decrypted", 0

                page_count = len(pdf_reader.pages)

                if page_count == 0:
                    return False, "PDF has no pages", 0

                # Quick validation of first page only for performance
                if page_count > 0:
                    try:
                        page = pdf_Reader.pages[0]
                        _ = page.extract_text()  # Try to extract text
                    except Exception as e:
                        return False, f"Page 1 extraction failed: {e}", page_count

                return True, None, page_count

        except Exception as e:
            return False, f"PDF validation error: {e}", 0

    def extract_text_with_pypdf2(self, file_path: str, page_range: str) -> List[List[str]]:
        """Extract text from PDF using PyPDF2 with optimized parsing"""
        try:
            with open(file_path, 'rb') as file:
                pdf_reader = PyPDF2.PdfReader(file)
                total_pages = len(pdf_reader.pages)

                # Parse page range efficiently
                if '-' in page_range:
                    start_str, end_str = page_range.split('-')
                    try:
                        start = max(1, int(start_str))
                        end = min(total_pages, int(end_str))
                        if start > end:
                            start, end = end, start
                        pages_to_process = range(start-1, end)
                    except ValueError:
                        pages_to_process = range(min(10, total_pages))  # Process first 10 pages max
                else:
                    try:
                        page_num = int(page_range)
                        pages_to_process = [min(page_num, total_pages) - 1]
                    except ValueError:
                        pages_to_process = range(min(10, total_pages))  # Process first 10 pages max

                text_data = []
                for page_num in pages_to_process:
                    try:
                        if page_num >= total_pages:
                            break

                        page = pdf_reader.pages[page_num]
                        text = page.extract_text()

                        if text and text.strip():
                            # Optimized text parsing
                            lines = text.split('\n')
                            for line in lines:
                                line = line.strip()
                                if line:
                                    # Split by 2+ spaces or tabs
                                    columns = [col.strip() for col in re.split(r'\s{2,}|\t', line) if col.strip()]
                                    if columns:
                                        text_data.append(columns)
                    except Exception:
                        continue  # Skip problematic pages

                return text_data

        except Exception:
            return []

