    def process_folder_to_csv(self, folder_path: str, output_file: str = "combined_statements.csv") -> Optional[str]:
        """Process all PDFs in folder and generate sorted CSV"""
        try:
            # Get all PDF files
            pdf_files = list(Path(folder_path).glob("*.pdf")) + list(Path(folder_path).glob("*.PDF"))

