template<typename T>
class MatrixMinorCalculator {
private:
    std::vector<std::vector<T>> data;
    size_t n;

public:
    MatrixMinorCalculator(const std::vector<std::vector<T>>& mat) : data(mat), n(mat.size()) {
        if (n == 0) throw std::invalid_argument("Matrix cannot be empty");
        for (const auto& row : data) {
            if (row.size() != n) throw std::invalid_argument("Matrix must be square");
        }
    }

    T minorDeterminant(size_t row, size_t col) const {
        if (row >= n || col >= n) throw std::out_of_range("Indices out of bounds");

        // Create minor matrix efficiently
        std::vector<std::vector<T>> minor;
        minor.reserve(n-1);
        for (size_t i = 0; i < n; ++i) {
            if (i == row) continue;
            std::vector<T> minorRow;
            minorRow.reserve(n-1);
            for (size_t j = 0; j < n; ++j) {
                if (j == col) continue;
                minorRow.push_back(data[i][j]);
            }
            minor.push_back(std::move(minorRow));
        }

        // Compute determinant
        return computeDeterminant(minor);
    }

private:
    T computeDeterminant(const std::vector<std::vector<T>>& mat) const {
        size_t m = mat.size();
        if (m == 1) return mat[0][0];
        if (m == 2) return mat[0][0]*mat[1][1] - mat[0][1]*mat[1][0];

        T det = 0;
        int sign = 1;

        for (size_t j = 0; j < m; ++j) {
            // Create submatrix
            std::vector<std::vector<T>> submat;
            submat.reserve(m-1);
            for (size_t i = 1; i < m; ++i) {
                std::vector<T> row;
                row.reserve(m-1);
                for (size_t k = 0; k < m; ++k) {
                    if (k != j) row.push_back(mat[i][k]);
                }
                submat.push_back(std::move(row));
            }

            det += sign * mat[0][j] * computeDeterminant(submat);
            sign *= -1;
        }

        return det;
    }
};
